/**
 * Verify the snapshot counts are aggregated when the content summary of a
 * mount point with multiple destinations is computed.
 */
@Test
public void testContentSummaryWithSnapshot() throws Exception {
  Path path = new Path("/testContentSummaryWithSnapshot");
  Map<String, String> destMap = new HashMap<>();
  destMap.put("ns0", "/testContentSummaryWithSnapshot");
  destMap.put("ns1", "/testContentSummaryWithSnapshot");
  MountTable addEntry =
      MountTable.newInstance("/testContentSummaryWithSnapshot", destMap);
  addEntry.setDestOrder(DestinationOrder.HASH_ALL);
  assertTrue(addMountTable(addEntry));

  // Create a file and a directory in each subcluster, snapshot them and
  // then delete them, so the content only lives in the snapshot.
  for (DistributedFileSystem nnFs : Arrays.asList(nnFs0, nnFs1)) {
    nnFs.mkdirs(path);
    nnFs.allowSnapshot(path);
    nnFs.mkdirs(new Path(path, "dir"));
    DFSTestUtil.createFile(nnFs, new Path(path, "file"), 100L, (short) 1,
        1024L);
    nnFs.createSnapshot(path, "snap");
    assertTrue(nnFs.delete(new Path(path, "dir"), true));
    assertTrue(nnFs.delete(new Path(path, "file"), true));
  }

  ContentSummary ns0Cs = nnFs0.getContentSummary(path);
  ContentSummary ns1Cs = nnFs1.getContentSummary(path);
  ContentSummary cs = routerFs.getContentSummary(path);
  assertTrue(ns0Cs.getSnapshotDirectoryCount() > 0);
  assertTrue(ns0Cs.getSnapshotFileCount() > 0);
  assertEquals(
      ns0Cs.getSnapshotDirectoryCount() + ns1Cs.getSnapshotDirectoryCount(),
      cs.getSnapshotDirectoryCount());
  assertEquals(ns0Cs.getSnapshotFileCount() + ns1Cs.getSnapshotFileCount(),
      cs.getSnapshotFileCount());
}

